
#define main archived_prefetch_main
#include "../prefetch-cuda/main.cu"
#undef main
#include <vector>
#include <string>
#define CK(c) do{cudaError_t e=(c);if(e!=cudaSuccess){fprintf(stderr,"%s\n",cudaGetErrorString(e));exit(2);}}while(0)
struct Case{int n;bool mode;float*a,*b;};
void init(Case&c){for(int i=0;i<c.n;i++){c.a[i]=c.n==4099?1.f:float(i%17-8)/16.f;c.b[i]=c.n==4099?2.f:float((i*5)%23-11)/32.f;}}
int main(){int cma;CK(cudaDeviceGetAttribute(&cma,cudaDevAttrConcurrentManagedAccess,0));if(!cma){puts("CMA unsupported");return 3;}std::vector<Case>cs;std::vector<float>prefix;for(int n:{4099,1048579}){prefix.push_back(float(n));prefix.push_back(7);for(int i=0;i<n;i++)prefix.push_back(n==4099?1.f:float(i%17-8)/16.f);for(int i=0;i<n;i++)prefix.push_back(n==4099?2.f:float((i*5)%23-11)/32.f);for(bool mode:{true,false}){Case c;c.n=n;c.mode=mode;CK(cudaMallocManaged(&c.a,n*4));CK(cudaMallocManaged(&c.b,n*4));init(c);add<<<(n+255)/256,256>>>(n,c.a,c.b);cs.push_back(c);}}CK(cudaDeviceSynchronize());bool all=true;
for(int trial=1;trial<=5;trial++){for(auto&c:cs)init(c);CK(cudaDeviceSynchronize());std::vector<double>times;for(auto&c:cs){auto start=std::chrono::steady_clock::now();for(int r=0;r<7;r++){if(c.mode){cudaMemLocation loc;loc.type=cudaMemLocationTypeDevice;loc.id=0;CK(cudaMemPrefetchAsync(c.a,c.n*4,loc,0));CK(cudaMemPrefetchAsync(c.b,c.n*4,loc,0));}add<<<(c.n+255)/256,256>>>(c.n,c.a,c.b);CK(cudaGetLastError());CK(cudaDeviceSynchronize());}times.push_back(std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count()/7);}auto out=prefix;bool ok=true;double time=0;for(auto t:times)time+=t;for(auto&c:cs){for(int i=0;i<c.n;i++){float a=c.n==4099?1.f:float(i%17-8)/16.f;float b=c.n==4099?2.f:float((i*5)%23-11)/32.f;ok&=c.a[i]==a&&c.b[i]==b+7*a;out.push_back(c.a[i]);}for(int i=0;i<c.n;i++)out.push_back(c.b[i]);}all&=ok;std::string path=std::string(getenv("STUDY_OUTPUT_DIR")?getenv("STUDY_OUTPUT_DIR"):".")+"/output_trial"+std::to_string(trial)+".bin";FILE*f=fopen(path.c_str(),"wb");if(!f)return 4;fwrite(out.data(),4,out.size(),f);fclose(f);printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.12g,\"component_seconds\":[%.12g,%.12g,%.12g,%.12g],\"correct\":%s,\"checked_values\":4210712,\"max_abs_error\":%d,\"max_rel_error\":%d,\"timing_region\":\"kernel_launch_loop_per_internal_repeat\",\"jit_excluded\":true,\"internal_repeats\":7,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"float32\",\"count\":%zu,\"byte_order\":\"little\"}}\n",trial,time,times[0],times[1],times[2],times[3],ok?"true":"false",ok?0:1,ok?0:1,path.c_str(),out.size());}for(auto&c:cs){CK(cudaFree(c.a));CK(cudaFree(c.b));}puts(all?"PASS":"FAIL");return all?0:1;}
